func fixUpForPlainMode(y *limatype.LimaYAML) {
	if !*y.Plain {
		return
	}
	deleteNonStaticPortForwards(&y.PortForwards)
	y.Mounts = nil
	y.Containerd.System = ptr.Of(false)
	y.Containerd.User = ptr.Of(false)
	y.TimeZone = ptr.Of("")
}

